func _set_state(next: State) -> void:
	var entering: bool = next != state or anim.assigned_animation != CLIPS[next]
	state = next
	if entering:
		_play(CLIPS[next])
	sprite.flip_h = facing < 0


## From the clip's first frame, applied at once (as the texture write was), on the physics callback from then on.
func _play(clip: StringName) -> void:
	anim.play(clip)
	anim.seek(0.0, true)

func take_damage(amount: int) -> void:
	if dead:
		return
	hp -= amount
	_flash()
	if hp > 0:
		if state == State.GROWL:
			_enter(State.RECOVER)
			# The hit is resolved before this tick's update, and the clip advances one frame in that update: seeking one
			# frame early makes the hit tick show frame 53, as a normal RECOVER entry does (tests/test_anim_edges.gd).
			anim.seek((RECOVER_FRAME - 1) / 60.0, true)
		return
